set -euo pipefail; python3 - <<'PY'
import json, pathlib, shlex, subprocess
build=pathlib.Path('build/idf-stage28e-d1-runtime-owner-gate')
cc=json.loads((build/'compile_commands.json').read_text())
e=next(x for x in cc if x['file'].endswith('/src/climate/ClimateV6RealInputRuntime.cpp'))
args=list(e.get('arguments') or shlex.split(e['command']))
out='/tmp/stage28e_d1_runtime.o'
for i,a in enumerate(args):
    if a=='-o' and i+1<len(args): args[i+1]=out
args.append('-fstack-usage')
subprocess.run(args,cwd=e['directory'],check=True)
sus=list(pathlib.Path('/tmp').glob('stage28e_d1_runtime*.su'))
if not sus: raise SystemExit('stack usage file missing')
frame=None
for p in sus:
    for line in p.read_text(errors='replace').splitlines():
        if 'runClimateV6RealInputRuntime' not in line: continue
        parts=line.rsplit('\t',2)
        if len(parts)==3:
            frame=int(parts[1]); print('STAGE28E_D1_RUNTIME_FRAME_BYTES',frame)
if frame is None: raise SystemExit('runtime frame not found')
if frame >= 5296: raise SystemExit(f'frame did not improve: {frame}')
if frame > 4000: raise SystemExit(f'frame reduction smaller than expected: {frame}')
print('STAGE28E_D1_STACK_REDUCTION_BYTES',5296-frame)
print('STAGE28E_D1_STACK_USAGE_PASS')
PY

